const r = await tools.exec_command({"cmd":"set -eu
node -e 'const fs=require("fs"); for (const f of ["out/audit.json","out/eval-manifest.json"]) JSON.parse(fs.readFileSync(f,"utf8")); const m=JSON.parse(fs.readFileSync("out/eval-manifest.json","utf8")); const d=m.cases.filter(x=>x.split==="development").length; const h=m.cases.filter(x=>x.split==="holdout").length; if(m.cases.length<8||h<2||m.cases.some(x=>!x.expected_behavior)) process.exit(1); console.log(JSON.stringify({case_count:m.cases.length,development:d,holdout:h,holdout_fraction:h/m.cases.length,evaluation_status:m.evaluation_status},null,2)); const a=JSON.parse(fs.readFileSync("out/audit.json","utf8")); console.log(JSON.stringify({findings:a.findings.length,traced_failures:a.failure_traceability.length,evaluation_status:a.evaluation_status},null,2));'
rg -n -i 'behavioral score|quality lift|battle result|chain-of-thought|production|named test|secrets|unrelated' out
wc -w current-prompt.md out/optimized-prompt.md out/behavioral-diff.md
sha256sum out/audit.json out/optimized-prompt.md out/eval-manifest.json out/behavioral-diff.md","workdir":"/app","yield_time_ms":10000,"max_output_tokens":20000});
text(r.output);
